def run(context):
    improving_sectors = context[
        'breadth.sector_daily'
    ].query('breadth_signal == "positive" & change_5d > 0')
    improving_sectors = improving_sectors[['sector', 'pct_above_50dma', 'change_5d']]
    context['sector_ranks'] = improving_sectors.sort_values(
        by=['pct_above_50dma', 'change_5d'], ascending=False
    )

    return {'improving_sectors': improving_sectors['sector'].tolist()}

